insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('integrity', 'intermediate', 'module', 'm01-why-annulus-pressure-matters', 1, 'Why does a modest temperature rise in a sealed annulus produce a large pressure rise?', '["Gas trapped at the top of the annulus expands as it warms.", "The steel walls contract as they take up heat from the produced fluid, squeezing the annulus volume down and driving pressure up.", "The trapped liquid is nearly incompressible, so the fixed volume offers almost no compliance to absorb expansion.", "The produced fluid leaks past the packer once the completion warms and loosens it."]'::jsonb, 2, 'Thermal pressure follows the production rate, and once bled off it does not return while the well stays at the same temperature.'),
  ('integrity', 'intermediate', 'module', 'm01-why-annulus-pressure-matters', 2, 'An annulus is bled to zero and the pressure returns while the well temperature is unchanged. What does that behaviour indicate?', '["A source is still connected to the annulus, which is sustained casing pressure and a barrier finding.", "Normal thermal expansion, which is acceptable to live with.", "Nothing either way, because a thermal build and a communication path are judged against completely different limits.", "An instrument fault on the annulus gauge, since a sealed volume cannot repressure itself."]'::jsonb, 0, 'Only one of the two causes is normally acceptable to live with, and the rebuild test is what separates them at the wellsite.'),
  ('integrity', 'intermediate', 'module', 'm01-why-annulus-pressure-matters', 3, 'Given a fluid density and a list of bounding elements, what does the annulus half of this engine return?', '["Whether the observed pressure is thermal or a communication leak.", "How much surface pressure those elements will carry, with cause, rate and time left outside the calculation.", "A time to build for the annulus, so an operator can judge whether the pressure on the gauge is still growing or has settled.", "A leak rate in cubic metres per day for the element that is passing fluid."]'::jsonb, 1, 'Both a thermal build and a leak are measured against the same limit, so the limit alone never tells you which one you have.'),
  ('integrity', 'intermediate', 'module', 'm01-why-annulus-pressure-matters', 4, 'Raising the annulus fluid from 1030 to 2000 kg/m3 on the published limiting element does what to the allowable?', '["It holds at 24000000 Pa, because the element rating is unchanged.", "It climbs steadily, because a heavier packer fluid holds more pressure down and therefore leaves more room at surface.", "It falls only if the fluid on the far side is changed to match the new annulus density.", "It falls from 24000000 Pa to 4515713.910002284 Pa, because a heavier column already stands on the element."]'::jsonb, 3, 'The published case carries 1200 kg/m3, which already gives up several megapascals against the lightest fluid in the sweep.'),
  ('integrity', 'intermediate', 'module', 'm01-why-annulus-pressure-matters', 5, 'What follows from the point that choosing a packer fluid is choosing part of the annulus pressure limit?', '["Part of the limit is fixed at completion design time, before a single degree of heating has happened.", "The limit depends only on the ratings of the bounding steel.", "The packer fluid may be picked after the limit is agreed, since density feeds the rated term rather than the standing head.", "A lighter packer fluid always reduces the allowable surface pressure."]'::jsonb, 0, 'That is why a packer fluid selection belongs in the integrity case and not only in the corrosion or the freezing point argument.'),
  ('integrity', 'intermediate', 'module', 'm01-why-annulus-pressure-matters', 6, 'Pressure inside an annulus acts on the wall outside it and the wall inside it. In which senses are the two loaded?', '["Both walls are loaded in burst by the annulus pressure.", "The outer casing is loaded in collapse and the inner string in burst, because pressure acts outward from the annulus centre.", "The outer casing is loaded in burst while the inner string is loaded in collapse, both by the same pressure.", "Only the inner string is loaded, since the outer casing is supported by its cement sheath."]'::jsonb, 2, 'Because the two senses appear together, an annulus limit is a comparison across the bounding elements rather than one rating to look up.'),
  ('integrity', 'intermediate', 'module', 'm01-why-annulus-pressure-matters', 7, 'On the published candidate list the 9-5/8 casing carries the highest limit at 40000000 Pa. Which element governs?', '["The 9-5/8 production casing burst, because it carries the highest rating.", "The 4-1/2 tubing collapse governs, so the largest rating on the list is not the deciding one.", "The 7 in production liner burst, because a liner is the shortest string in the well and has the least support behind it.", "Whichever element was supplied first, since the engine keeps the top row of the table."]'::jsonb, 1, 'The list mixes elements loaded in burst with elements loaded in collapse, so ranking by rating alone crosses two different failure modes.'),
  ('integrity', 'intermediate', 'module', 'm01-why-annulus-pressure-matters', 8, 'Why can a shoe formation set the annulus limit even when the casing around it is rated far higher?', '["It cannot, because only steel elements bound an annulus.", "Because the engine derates a shoe formation heavily, which pulls its allowable below every steel candidate on the list.", "Because a formation is always shallower than the casing shoe standing above it.", "Pressure in an annulus open to a formation can break it down and broach, so fracture strength becomes the limit."]'::jsonb, 3, 'A shoe formation is one of two bounding roles that are not pipe at all, and its limit comes from a leak off test rather than a tally.'),
  ('integrity', 'intermediate', 'module', 'm01-why-annulus-pressure-matters', 9, 'A wellhead or tree rating sits at the top of an annulus. What follows from where it sits?', '["It stands at zero vertical depth, so it feels the surface pressure with no help from any fluid column.", "It is left out of the table because it is not downhole equipment.", "Its hydrostatic term is the largest in the table, since the whole annulus column stands above it at the wellhead.", "It carries a backup density equal to the annulus fluid by default."]'::jsonb, 0, 'An element at zero depth reduces to its rated term alone, which makes it a useful check that the head arithmetic is behaving.'),
  ('integrity', 'intermediate', 'module', 'm01-why-annulus-pressure-matters', 10, 'An annulus is reading comfortably below its calculated limit. What may be concluded about that well?', '["That the annulus is sound and needs no further attention.", "That any leak feeding the annulus is small enough to tolerate, because the limit accounts for how fast pressure returns.", "Only that no bounding element is overloaded today if the reading holds, which is not a verdict on health.", "That the barrier envelope containing the annulus must be intact."]'::jsonb, 2, 'Whether the pressure should be there at all is the barrier question from the Associate tier, with a separate answer.'),
  ('integrity', 'intermediate', 'module', 'm01-why-annulus-pressure-matters', 11, 'Both entry points share one copy of the row arithmetic. Where does the difference between them sit?', '["In the value of gravity each path uses for the hydrostatic term.", "Upstream of the shared call, because an element brings its own factor and a candidate brings a role to be looked up.", "In the clamp, since one path reports the raw negative allowable and the other is the only one that returns zero.", "In the sorting, because one path returns its rows ordered by allowable."]'::jsonb, 1, 'The mawop path builds an element list and then calls maaspRows, so there is exactly one copy of the row formula to maintain.'),
  ('integrity', 'intermediate', 'module', 'm01-why-annulus-pressure-matters', 12, 'What happens when elements reach maaspRows with no factor supplied on any of them?', '["The call throws, because a factor is a required field.", "The engine falls back to the RP 90 role table and applies 0.5, 0.8 or 0.75 to each element according to what it is.", "Every element is given 0.75, the middle value of the published factor table.", "The engine uses 1 throughout, so what comes back is the bare physical allowable with nothing held back."]'::jsonb, 3, 'Supplied factors are checked against the interval above zero up to and including 1, but the engine has no view on which value is right.'),
  ('integrity', 'intermediate', 'module', 'm01-why-annulus-pressure-matters', 13, 'A candidate reaches mawop carrying a role that the factor table does not contain. How does the engine respond?', '["It throws, so a misspelled role cannot quietly collect a factor of 1 and pass at full rating.", "It applies a factor of 1 to that candidate and carries on.", "It drops the candidate from the list and computes the governing row from whichever of the remaining candidates are valid.", "It substitutes the strictest value in the table, which is 0.5."]'::jsonb, 0, 'The factor table is an argument and can be replaced, but a role outside whichever table is in force is always a stop.'),
  ('integrity', 'intermediate', 'module', 'm01-why-annulus-pressure-matters', 14, 'Why are the clamp at zero and the negative flag described as working only as a pair?', '["Because both of them are computed from the top row of the table.", "Because the clamp is applied before the governing row is picked, so the flag is the only record of which row went negative.", "A bare zero hides a design problem, and a raw negative invites someone to treat it as a reachable pressure.", "Because the flag counts how many rows in the table fell below zero."]'::jsonb, 2, 'Raise the published annulus fluid to 2250 kg/m3 and the governing row allows minus 506009.3090692945 Pa, reported as zero with the flag up.'),
  ('integrity', 'intermediate', 'module', 'm01-why-annulus-pressure-matters', 15, 'The published limiting element sits at 2400 m measured and 2048.29303343 m vertical. Why does that distinction matter?', '["It does not matter, because the engine converts the depth itself.", "A pressure head is a vertical quantity, so a measured depth would inflate every hydrostatic term on a deviated well.", "Because the engine stores measured depth for the rated term and vertical depth for the head, so mixing them swaps the two.", "Because measured depth would understate the head and overstate the allowable."]'::jsonb, 1, 'The conversion belongs to the survey engine, and every element in this table carries tvdM rather than a depth along hole.'),
  ('integrity', 'intermediate', 'module', 'm02-maasp', 1, 'Change one element''s rating in a MAASP table and what moves?', '["Every row, since the rating feeds the shared annulus fluid column.", "Only that element''s own row, because the rows are independent and each one answers for itself alone.", "That row and the row directly beneath it, because each element carries part of the load standing on the element below.", "Nothing until the governing element itself is edited."]'::jsonb, 1, 'That independence is what makes the table readable, because any change in the final number can be attributed to a single line.'),
  ('integrity', 'intermediate', 'module', 'm02-maasp', 2, 'Which two terms make up the allowable surface pressure on a single MAASP row?', '["The rated term less the friction loss down the annulus.", "The rated term of the element added to the hydrostatic term, because a column of fluid helps hold surface pressure down.", "The element limit less the pressure measured at the wellhead today.", "The rated term, factor times limit, less the differential head that the standing fluid columns already impose."]'::jsonb, 3, 'The first term belongs to the hardware and the second belongs to the well, which is why they respond to entirely different edits.'),
  ('integrity', 'intermediate', 'module', 'm02-maasp', 3, 'Across the three published rows, which quantity is shared by all of them?', '["The annulus fluid density, which is the one property the annulus itself owns rather than any element.", "The true vertical depth, since all three elements bound the same annulus.", "The backup density, because the fluid on the far side of a bounding wall is a property of the annulus rather than the element.", "The design factor, which the engine applies uniformly to the list."]'::jsonb, 0, 'Three depths, three backup densities and three factors sit in that table, so each row carries almost all of its own inputs.'),
  ('integrity', 'intermediate', 'module', 'm02-maasp', 4, 'The engine returns rows in the order they were supplied and never sorts them. What does that imply for a reader?', '["Rows should be supplied strictly from shallowest to deepest.", "The reader may take the top row as the governing one, because the engine places the strictest candidate there deliberately.", "Position carries no meaning at all, so the top row is not the important one and must not be read as such.", "Sorting is left to the panel, which orders rows by allowable before display."]'::jsonb, 2, 'Preserving the supplied order keeps a row lined up with the element the user typed, which matters when a name has to be traced back.'),
  ('integrity', 'intermediate', 'module', 'm02-maasp', 5, 'Which input does the engine reject before it builds any row at all?', '["A backup density above the annulus fluid density.", "An annulus fluid density that is not positive, which is refused ahead of the whole table.", "A wellhead element at zero vertical depth, because a row with no hydrostatic term cannot be compared with the others.", "A candidate list that contains two elements with the same name."]'::jsonb, 1, 'Per row it also throws on a limit that is not above zero, on a negative TVD, and on a factor outside the interval above zero up to 1.'),
  ('integrity', 'intermediate', 'module', 'm02-maasp', 6, 'Why does the lesson call limitPa the input most often wrong on a real well?', '["The engine cannot derive it or check it, and it comes off a tally that may not describe the pipe in the hole.", "Because the engine stores it in pascals rather than in psi.", "Because it is recomputed from the factor each time the row is built, so any error in the factor propagates straight into it.", "Because a burst rating and a collapse rating are held in the same field."]'::jsonb, 0, 'A wrong limit is invisible in the arithmetic, since every row will compute cleanly and return a plausible looking allowable.'),
  ('integrity', 'intermediate', 'module', 'm02-maasp', 7, 'The engine refuses a factor of 1.2 and it also refuses a factor of zero. What are the two reasons?', '["Both values fall outside the range the row arithmetic can hold.", "Above 1 would make the rated term exceed the hydrostatic term, and zero would leave the row with a negative allowable.", "Both are refused only when the element also carries a zero backup density.", "Above 1 is an uprate rather than a derate, and zero describes a failed element rather than a derated one."]'::jsonb, 3, 'An element with no capacity belongs in the barrier envelope work from the Associate tier rather than in an allowable pressure table.'),
  ('integrity', 'intermediate', 'module', 'm02-maasp', 8, 'An annulus at 1200 kg/m3 with 1030 behind a wall loads that element identically to an annulus at 1030 with 860 behind it. Why?', '["Because the engine normalises every density to fresh water.", "Because the deeper of the two elements always dominates, and the two cases were quoted at the same true vertical depth.", "Only the difference of the two densities enters the head, and that difference is identical in the two cases.", "Because a backup fluid lighter than the annulus fluid is ignored."]'::jsonb, 2, 'A rating is a differential across a wall, so a heavy fluid on the far side is help rather than hazard.'),
  ('integrity', 'intermediate', 'module', 'm02-maasp', 9, 'At the published limiting element''s depth, one kilogramme per cubic metre of density difference is worth how much?', '["It is worth 20086.892876286307 Pa of allowable, gained on the backup side and lost on the annulus side.", "It is worth 9.80665 Pa, which is the gravity constant itself.", "It is worth 20086.892876286307 Pa, and the sign is the same whichever of the two densities was the one that moved.", "It is worth nothing measurable until the density difference grows large."]'::jsonb, 0, 'The gradient against annulus density is the negative of the one against backup density, and the magnitudes match because it is one term.'),
  ('integrity', 'intermediate', 'module', 'm02-maasp', 10, 'Backup density is omitted on an element. What has been modelled?', '["Nothing, because the engine then skips the hydrostatic term.", "A gas filled or evacuated volume on the far side, which is the worst case rather than a neutral assumption.", "A far side holding the same fluid as the annulus, which is the safest default the engine could pick on the user''s behalf.", "A far side at the local formation pressure at that depth."]'::jsonb, 1, 'In the published backup sweep the zero row is the only one that turns the allowable negative, at minus 104271.45154356956 Pa.'),
  ('integrity', 'intermediate', 'module', 'm02-maasp', 11, 'How does the engine pick the governing row out of the table?', '["It keeps the row with the lowest element limit before any factor.", "It keeps the first row supplied, which is why the lesson insists that candidates are listed with the weakest element first.", "It scans every row and keeps the smallest allowable, with the top row present only as an incumbent to be beaten.", "It keeps the deepest row, since depth drives the hydrostatic deduction."]'::jsonb, 2, 'The comparison in the loop is strictly less than, which is what gives the reduction its tie behaviour.'),
  ('integrity', 'intermediate', 'module', 'm02-maasp', 12, 'Suppose the reduction returned the first row rather than the minimum on the published candidates. What would be reported?', '["It would report the same value, since the rows happen to tie.", "It would report 26855228.63225454 Pa, because the liner row is the least constraining of the three and would take over the answer.", "It would raise the negative flag, because the wrong row was picked.", "It would report 17606905.05541501 Pa, offering 5701240.88444588 Pa the tubing cannot take as though it could."]'::jsonb, 3, 'No arithmetic error and no implausible number would appear, which is exactly why this class of defect survives a numeric review.'),
  ('integrity', 'intermediate', 'module', 'm02-maasp', 13, 'Every row in a table is verified against an oracle to the last decimal. What remains unverified?', '["The fold that turns those rows into one number, because a pick is logic with a rule rather than arithmetic.", "Nothing, since the governing value is one of the verified rows.", "The units, because an oracle checks magnitudes rather than whether each row was returned in pascals or in psi.", "The order of the rows, which the oracle cannot see."]'::jsonb, 0, 'A sibling course shipped this defect: a casing check took the bottom of the section instead of searching, so every pressure was right and the pick was not.'),
  ('integrity', 'intermediate', 'module', 'm02-maasp', 14, 'In what order are the clamp and the pick applied, and which row does the flag describe?', '["The clamp comes first, so negative rows never reach the pick.", "The clamp comes after the pick, and the flag is raised whenever any row in the table is negative, whether or not it governs.", "The clamp comes after the pick, and the flag reports on the governing row, which is the smallest of them.", "The clamp and the flag are both applied per row before the reduction."]'::jsonb, 2, 'Because the governing row is the minimum, no other row can be negative while the governing row is not.'),
  ('integrity', 'intermediate', 'module', 'm02-maasp', 15, 'Two rows come back with identical allowables. Which name does the engine report and why does it matter?', '["The later row wins, because the loop overwrites on equality.", "The earlier row keeps the name, and the element sent for inspection differs even though the reported limit does not.", "The engine reports both names, so that a reader can see the tie and go and inspect either of the two elements on the list.", "The engine throws, because a tie leaves the governing row undefined."]'::jsonb, 1, 'A near tie is a signal to read the whole list, since a modest change of fluid can hand the limit to different hardware with a different failure mode.'),
  ('integrity', 'intermediate', 'module', 'm03-mawop-and-the-rp90-factors', 1, 'What does the engine ask about a candidate before it decides how much of the rating may be used?', '["It asks for the outside diameter and the wall thickness.", "It asks for the grade of the steel, since a higher grade earns a larger fraction of the rating in the RP 90 convention.", "It asks what job the element is doing, because the role rather than the pipe selects the design factor.", "It asks when the string was last pressure tested."]'::jsonb, 2, 'RP90_MAWOP_FACTORS holds five entries and nothing else, so a well described in any other vocabulary has to be translated first.'),
  ('integrity', 'intermediate', 'module', 'm03-mawop-and-the-rp90-factors', 2, 'Which description matches the outer-casing-burst role?', '["Any casing string that was run before the production casing.", "A string with another annulus or the formation outside it, pressured from within and not readily inspectable.", "The outermost string in the well, meaning the conductor or the surface casing, which is the only one exposed to the seabed.", "A casing string whose burst rating is lower than its collapse rating."]'::jsonb, 1, 'The label describes a relationship to the annulus being calculated, so the same string can hold different roles on different annuli.'),
  ('integrity', 'intermediate', 'module', 'm03-mawop-and-the-rp90-factors', 3, 'What is a candidate declaring when it is given the role called rating?', '["That the element has never been given a formal pressure rating.", "That the engine should choose the strictest factor available, because a bare rating carries no information about how the element is used.", "That the limit came from a manufacturer rather than from a test.", "That the supplied limit is already the working limit and the engine should take it at face value."]'::jsonb, 3, 'It is the escape hatch in the table, and like shoe-formation it carries a factor of 1.0 so nothing further is held back.'),
  ('integrity', 'intermediate', 'module', 'm03-mawop-and-the-rp90-factors', 4, 'Why does shoe-formation carry a factor of 1.0 rather than a derate?', '["The fracture limit at the shoe was already established by a leak off test, so there is nothing further to hold back.", "Because a formation cannot burst in the way a steel string can.", "Because the engine has no way to model rock, so it passes the limit through unchanged and expects the user to derate it by hand.", "Because a shoe is always the deepest element bounding the annulus."]'::jsonb, 0, 'That role is not steel at all, which is also why no inspection or repair argument applies to it.'),
  ('integrity', 'intermediate', 'module', 'm03-mawop-and-the-rp90-factors', 5, 'A candidate is switched from one role to another and nothing else about it changes. Which part of the row moves?', '["Both terms move, in proportion to the new factor.", "Only the differential head moves, because the role tells the engine which side of the wall the backup fluid sits on.", "Only the rated term moves, and it moves by a fixed proportion, so the differential head is untouched.", "The row is rebuilt from scratch and the true vertical depth is reread."]'::jsonb, 2, 'The role sweep in the lesson holds the hydrostatic term at 2393094.944584991 Pa across all five runs for exactly that reason.'),
  ('integrity', 'intermediate', 'module', 'm03-mawop-and-the-rp90-factors', 6, 'A candidate arrives carrying a role that is not in the factor table. What does mawop do?', '["It throws and names the candidate in the message, rather than defaulting to anything more permissive.", "It falls back to the strictest entry in the table, 0.5.", "It computes the row with a factor of 1 and marks the row so that a reviewer can see which candidate was not recognised.", "It removes the candidate and reduces over the ones that remain."]'::jsonb, 0, 'An unrecognised role is either a typing error or a convention the engine has not been taught, and each of those deserves a stop.'),
  ('integrity', 'intermediate', 'module', 'm03-mawop-and-the-rp90-factors', 7, 'Two sound strings of the same steel are allowed 0.8 and 0.5 of their ratings. What accounts for the difference?', '["The depth at which each of the two strings is set.", "Access rather than metallurgy, since one string can be inspected, repaired and monitored far more readily.", "The manufacturing tolerance on the two strings, which the rating already carries and which the factor is there to express again.", "The difference between a burst rating and a collapse rating."]'::jsonb, 1, 'Under those two roles the same 40000000 Pa candidate allows 29606905.05541501 Pa and 17606905.05541501 Pa on an otherwise identical row.'),
  ('integrity', 'intermediate', 'module', 'm03-mawop-and-the-rp90-factors', 8, 'Why is a leak from an outer string described as harder to detect than one from an inner string?', '["Because outer strings are not fitted with an annulus gauge.", "Because an outer string leak shows up immediately as a pressure rise, which is dismissed as thermal and therefore never investigated.", "Because the leak rate from an outer string is always smaller.", "It vents into a formation, a shallower annulus or the seabed rather than into the annulus being watched."]'::jsonb, 3, 'The first sign may be a sustained pressure that will not bleed down, or a shallow gas indication a long way from the wellhead.'),
  ('integrity', 'intermediate', 'module', 'm03-mawop-and-the-rp90-factors', 9, 'What is the design factor actually buying, according to the lesson?', '["A margin against the manufacturing tolerance on the pipe.", "Time and evidence, meaning room for wear not measured, corrosion not logged and a leak not yet noticed.", "A prediction of the pressure at which the steel will part, expressed as a fraction of the nominal rating from the tally.", "An allowance for the temperature the string will see in service."]'::jsonb, 1, 'The rating already carries the manufacturing allowance, so a factor that is read as a strength estimate is being read twice over.'),
  ('integrity', 'intermediate', 'module', 'm03-mawop-and-the-rp90-factors', 10, 'Which candidate governs the published MAWOP case, and on how many counts does it win?', '["The 9-5/8 casing burst, on the single count of the harshest factor.", "The 7 in liner burst, because it sits between the other two on depth and on rating and therefore carries the middle allowable.", "The 4-1/2 tubing collapse, winning on three counts at once: smallest limit, a 0.75 factor and the thinnest backup.", "The shallowest candidate, since depth sets the hydrostatic deduction."]'::jsonb, 2, 'Its 500 kg/m3 backup gives it the heaviest hydrostatic deduction of the three even though it is the shallowest candidate on the list.'),
  ('integrity', 'intermediate', 'module', 'm03-mawop-and-the-rp90-factors', 11, 'The 9-5/8 carries the harshest factor of the three published candidates. Why does it not govern?', '["Its 40000000 Pa limit is large enough that even half of it still clears the tubing row comfortably.", "Because an outer string is excluded from the reduction.", "Because the reduction ranks candidates by factor before it ranks them by allowable, and a tie on factor is broken by depth.", "Because its backup density of 1030 kg/m3 removes its hydrostatic term."]'::jsonb, 0, 'A reader who stops at the factor column will name the wrong string, because the engine ranks neither ratings nor factors.'),
  ('integrity', 'intermediate', 'module', 'm03-mawop-and-the-rp90-factors', 12, 'What makes the 7 in production liner the least constraining of the published candidates?', '["Its factor of 0.8, which is the loosest in the whole table.", "Its position in the middle of the supplied list, since the reduction keeps whichever row sits furthest from the incumbent it started with.", "Its depth of 1167.3419238429642 m, the shallowest of the three.", "A backup density of 1100 kg/m3, denser than the annulus fluid itself, which lightens its hydrostatic deduction."]'::jsonb, 3, 'It allows 26855228.63225454 Pa, so the governing margin on this well is measured against the 9-5/8 instead.'),
  ('integrity', 'intermediate', 'module', 'm03-mawop-and-the-rp90-factors', 13, 'One limit, one depth, one pair of fluids, and five roles give allowables spanning 20000000 Pa. What does that show?', '["That the hydrostatic term is highly sensitive to the role.", "That the engine applies the factor twice on the looser roles, once to the rating and once again to the differential head.", "The limit written on the operating card is a property of the role assigned, not of the pipe that was run.", "That the spread comes from the depth being reread on each run."]'::jsonb, 2, 'After a tieback a string that was inner casing can become the outer string, and the same steel then loses 20000000 Pa of rated capacity on paper.'),
  ('integrity', 'intermediate', 'module', 'm03-mawop-and-the-rp90-factors', 14, 'Why does inner-tubing-collapse sit below inner-casing-burst in the factor table?', '["The hierarchy tracks how well an element can be seen and how bad an undetected failure would be, not its size.", "Because tubing is the thinnest string and the weakest in the well.", "Because collapse is a buckling failure and the convention derates every buckling mode to three quarters of the nominal rating.", "Because the tubing sits shallower than the casing it hangs inside."]'::jsonb, 0, 'Diameter, wall thickness and nominal strength are already inside the limit that was supplied, so the factor must not repeat them.'),
  ('integrity', 'intermediate', 'module', 'm03-mawop-and-the-rp90-factors', 15, 'A candidate carries its own factor and also carries a role. Which value does mawop use?', '["The role default, since the table is the authority on derating.", "The candidate''s own factor, because a measurement should beat a convention, while the role still travels as the kind.", "The stricter of the two values, so that an explicit factor can tighten a role default but can never loosen one on its own.", "The product of the two, which compounds wear onto the role."]'::jsonb, 1, 'Nothing stops someone writing 0.9 against an outer casing whose default is 0.5, and only a review will catch that quiet uprate.'),
  ('integrity', 'intermediate', 'module', 'm04-the-differential', 1, 'Why does this module insist that a burst rating is not a pressure the pipe can hold?', '["A wall carries the gap between the pressure inside it and outside it, so a rating needs two sides named.", "Because the rating is derated by a role factor.", "Because ratings are published as gauge pressures, and gauge pressure is already a difference taken against the atmosphere outside.", "Because the mill quotes burst and collapse as a matched pair for every joint."]'::jsonb, 0, 'The bracket in the row is a difference of densities for the same reason, and it becomes a pressure only once multiplied by g and by the element''s true vertical depth.'),
  ('integrity', 'intermediate', 'module', 'm04-the-differential', 2, 'In the maaspRows expression, what does the bracketed term hold?', '["The annulus fluid density taken on its own.", "The sum of the two fluid densities standing on either face of the wall.", "The difference between the annulus density and the backup density, which is a net weight per unit volume.", "The average of the annulus and backup densities, taken so that a single equivalent column can be charged over the depth."]'::jsonb, 2, 'That bracket is a density and not yet a pressure, and it only becomes one when g and the element''s vertical depth are applied to it.'),
  ('integrity', 'intermediate', 'module', 'm04-the-differential', 3, 'Set the annulus density equal to the backup density in the panel. What does the row then return?', '["Zero, because the two columns cancel each other out completely.", "The rated term exactly, because the differential head vanishes and nothing is subtracted from it.", "The unfactored limit, because the role factor no longer has anything left to act upon.", "Half of the rated term, because each of the two equal columns is charged over half of the element''s vertical depth."]'::jsonb, 1, 'On the published fixture that rated term is 24000000 Pa, which is a factor of 0.8 applied to a limit of 30000000 Pa.'),
  ('integrity', 'intermediate', 'module', 'm04-the-differential', 4, 'The fixture element sits at 2400 m measured and 2048.29303343 m vertical. What follows from using the measured figure in the row?', '["The allowable rises, so the row reads as unsafely generous.", "Nothing moves, since only the density difference sets the head.", "The row is rejected by the engine, because maaspRows validates every depth against the survey before it builds a hydrostatic term.", "The head is inflated, so the allowable comes out too low and the mistake disguises itself as conservatism."]'::jsonb, 3, 'A hydrostatic column responds to vertical distance alone, and on this well the two depths differ by more than 350 m.'),
  ('integrity', 'intermediate', 'module', 'm04-the-differential', 5, 'How does maaspRows read an element whose backup density field was left blank?', '["It copies the annulus density across to the far side.", "It applies el.backupDensityKgM3 with a nullish default of zero, so the far side is evaluated as a void.", "It substitutes a nominal brine of 1030 kg/m3, matching the published case.", "It throws an error naming the element, on the grounds that an unspecified far side cannot become a defensible head."]'::jsonb, 1, 'The default is applied silently because a silent severe assumption is safer to ship than a silent generous one.'),
  ('integrity', 'intermediate', 'module', 'm04-the-differential', 6, 'What is the operating consequence of leaving the fixture''s backup field blank?', '["The row returns -104271.45154356956 Pa, the negative flag is raised and the reported MAASP is clamped to zero.", "The allowable falls to 2908762.4798993766 Pa.", "The element keeps 20585228.21103133 Pa of allowable pressure.", "The allowable drops to roughly half of the rated term, which still leaves a workable envelope for routine annulus work."]'::jsonb, 0, 'One omitted field takes this element from a healthy operating envelope to none at all, and it does so without a warning of its own.'),
  ('integrity', 'intermediate', 'module', 'm04-the-differential', 7, 'When is a backup density of zero the right entry rather than a lapse?', '["Whenever the far side fluid has not been sampled.", "When the annulus fluid and the far side fluid share the same nominal density.", "Whenever the element sits above a packer, since fluid below a packer cannot load any wall standing above it.", "When a gas lifted tubing has unloaded, or an annulus has been bled to atmosphere and then left open."]'::jsonb, 3, 'The rule the lesson sets is that zero should be a decision you made and can defend, not a field you did not reach.'),
  ('integrity', 'intermediate', 'module', 'm04-the-differential', 8, 'What standard does the module set for filling in a backup density honestly?', '["Use the lightest density the completion tally will support.", "Average the densities recorded at each of the annual pressure tests.", "Write what you can prove stands there now, not what was pumped at the end of the last completion job.", "Take the completion programme figure, since it is the only value that has passed through a formal design review."]'::jsonb, 2, 'Packer fluid can be displaced and gas can migrate above a leaking gas lift valve, so a five year old figure proves very little.'),
  ('integrity', 'intermediate', 'module', 'm04-the-differential', 9, 'An element sits at a true vertical depth of 2048.29303343 m. What is one further kg/m3 of backup density worth to it?', '["It adds 3414771.788968672 Pa to the allowable.", "It adds nothing measurable until the far side density passes the annulus density.", "It adds 20086.892876286307 Pa of allowable surface pressure, and that figure holds at any limit or factor.", "It adds an amount that grows with the rated term, because the role factor multiplies both halves of the row."]'::jsonb, 2, 'The slope is g multiplied by the true vertical depth, so it is fixed the moment the element itself is fixed.'),
  ('integrity', 'intermediate', 'module', 'm04-the-differential', 10, 'How does the sensitivity on the annulus side compare with the sensitivity on the far side?', '["Larger, because the annulus column loads both walls at once.", "Identical in size and in sign, because one single term produces them both.", "Smaller by the ratio of the densities, since the annulus column is charged over the full depth and the backup over part.", "Equal in size and opposite in sign, so every extra kg/m3 in the annulus removes 20086.892876286307 Pa."]'::jsonb, 3, 'Both figures come out of the one hydrostatic term, which sees nothing but the difference of the two densities.'),
  ('integrity', 'intermediate', 'module', 'm04-the-differential', 11, 'With 2000 kg/m3 behind the wall the fixture allows 40069514.30102905 Pa, above its 30000000 Pa limit. Is that a defect?', '["No. The heavier outside column lets more pressure sit inside before the wall sees its rated difference.", "No, the excess is a rounding artefact near the balance point.", "Yes, since a factor of 0.8 can never produce an allowable above the raw rating.", "Yes, because the engine ought to clamp any allowable at the unfactored limit, the largest difference the steel can carry."]'::jsonb, 0, 'The whole of the excess above the rating rests on that column staying where it is, so it has to be defensible.'),
  ('integrity', 'intermediate', 'module', 'm04-the-differential', 12, 'Two adjacent annuli sit either side of a casing string. Which column is the backup for a row on that string taken in the inner annulus?', '["The fluid in the inner annulus itself.", "The fluid in the outer annulus, which stands on the far side of the wall and enters the row with a plus sign.", "The tubing contents, because they are the only column inside the completion.", "Whichever of the two columns is heavier, since the engine assigns the backup role to the denser fluid at each wall."]'::jsonb, 1, 'So the fluid you place in an annulus is a design input for the element inside it, not only a completion detail for the annulus it fills.'),
  ('integrity', 'intermediate', 'module', 'm04-the-differential', 13, 'Moving the outer column on the fixture from 1030 kg/m3 to 1200 kg/m3 does what to the allowable?', '["It leaves the allowable unchanged at 24000000 Pa.", "It lifts the allowable to the unfactored limit of 30000000 Pa.", "It lowers the allowable, because a denser column on either face of a wall always adds to the load that wall carries.", "It lifts the allowable by 3414771.788968672 Pa, at the standing rate for an element at this vertical depth."]'::jsonb, 3, 'The gain is bought with a fluid choice rather than a workover, which is what makes it such a cheap lever.'),
  ('integrity', 'intermediate', 'module', 'm04-the-differential', 14, 'Why is the same weight up worth more to some candidates on the published well than to others?', '["Because each candidate carries a different role factor.", "The slope is g times true vertical depth, so the deepest candidate at 1435.457478934607 m gains the most.", "Because the shallower candidates have already been clamped at zero.", "Because the deeper candidates carry the larger ratings, and the gain is proportional to the rated term of the row."]'::jsonb, 1, 'The three published candidates sit at 1435.457478934607 m, 1167.3419238429642 m and 997.0400302755012 m.'),
  ('integrity', 'intermediate', 'module', 'm04-the-differential', 15, 'What does this module conclude about weighting up one annulus in order to protect a string?', '["It creates margin at no cost, since no steel is altered.", "It is barred under RP 90 unless the annulus can be monitored continuously.", "It moves margin from one wall across to another rather than creating any, so every element must be rechecked.", "It has no net effect at all, because the same fluid enters two rows with opposite signs and the two always cancel."]'::jsonb, 2, 'The two effects cancel only where the two elements share a true vertical depth, and on a real well they rarely do.'),
  ('integrity', 'intermediate', 'module', 'm05-when-it-cannot-be-pressured', 1, 'The annulus column on the fixture is worth 24104271.45154357 Pa, yet only 3414771.788968672 Pa reaches the wall. Why?', '["Because the factor of 0.8 has already removed most of the column.", "Head is charged on the difference of the two densities, so 170 kg/m3 is billed rather than the full 1200.", "Because the column is charged over the measured depth and then corrected back to vertical by the survey engine.", "Because the engine charges head only over the interval below the packer."]'::jsonb, 1, 'The remainder of the column is held up by the brine standing on the far side, which is why that fluid is part of the answer.'),
  ('integrity', 'intermediate', 'module', 'm05-when-it-cannot-be-pressured', 2, 'Across the far side sweep on the fixture, which inputs actually moved?', '["The annulus density fell in step with the far side density.", "The role factor was relaxed row by row so that the rated term stayed constant while the head term was allowed to grow.", "The vertical depth and the far side density moved together.", "Only the density standing on the other side of the steel, since depth, rating, factor and annulus fluid were all held."]'::jsonb, 3, 'Holding everything else fixed is what makes the sweep readable, because any change in the last column has exactly one cause.'),
  ('integrity', 'intermediate', 'module', 'm05-when-it-cannot-be-pressured', 3, 'What does the linear price of 20086.892876286307 Pa per kg/m3 imply about a far side that is getting lighter?', '["The allowance is given back at the very same rate it was bought, so the loss is a slope and never a cliff.", "The loss accelerates once the far side falls below brine.", "The loss stops once the reported MAASP reaches zero.", "The loss depends on the rating, because a stronger element gives up its allowance more slowly than a weak one."]'::jsonb, 0, 'The last row of the sweep is not a different mechanism from the first, it is the same subtraction run until it runs out.'),
  ('integrity', 'intermediate', 'module', 'm05-when-it-cannot-be-pressured', 4, 'The fixture with nothing on the far side returns -104271.45154356956 Pa. What does that row actually state?', '["The element has failed and is leaking to the far side.", "The engine has lost precision near the balance point of the two columns.", "The fluid already standing in the annulus loads the wall past its factored rating before anything is applied.", "The annulus may still be pressured, but only downwards towards a vacuum reading rather than upwards from atmospheric."]'::jsonb, 2, 'The allowable is not merely small on that row, it is past the end, and the row comes back with its negative flag raised.'),
  ('integrity', 'intermediate', 'module', 'm05-when-it-cannot-be-pressured', 5, 'Why does the lesson stress that nothing was applied in the negative case?', '["Because the pump was lined up but never started.", "Because thermal expansion, communication and every other transient load sit well outside the rows that this engine builds.", "Because the negative flag only fires while the annulus valve is shut.", "Every other output in this tier allows for something you might do, whereas this one describes what already stands."]'::jsonb, 3, 'There is no valve open and no thermal build in the story, only 2048.29303343 m of 1200 kg/m3 fluid with nothing behind the wall.'),
  ('integrity', 'intermediate', 'module', 'm05-when-it-cannot-be-pressured', 6, 'Holding the annulus at 1200 kg/m3, the fixture row crosses zero at a far side density of 5.191019446649534 kg/m3. Why is that uncomfortable?', '["Because the crossing sits below the density of any real gas.", "Because the engine cannot resolve densities that small.", "The gap between a working element and one past its rating is measured in single figures, not in hundreds.", "Because it shows that any far side fluid lighter than brine will drive the row negative and fire the clamp."]'::jsonb, 2, 'Anything denser than that break-even leaves a positive and usable allowable, and anything lighter leaves a negative row.'),
  ('integrity', 'intermediate', 'module', 'm05-when-it-cannot-be-pressured', 7, 'Hold the far side at 1030 kg/m3 and raise the annulus density instead. Where does the same element cross?', '["At 1200 kg/m3, where the two columns balance.", "At 2224.8089805533505 kg/m3, with 498335.3347450197 Pa still allowed at 2200 kg/m3 on the way there.", "At 2250 kg/m3, which is the first density the sweep reports as negative.", "At the density that makes the head equal to the unfactored limit, since the factor cancels out of a break-even."]'::jsonb, 1, 'At 2250 kg/m3 the same element reports -506009.3090692945 Pa, so the crossing sits between the two sweep rows.'),
  ('integrity', 'intermediate', 'module', 'm05-when-it-cannot-be-pressured', 8, 'A heavier annulus and a lighter far side both drive a row negative. How many mechanisms is that?', '["One, because the row only ever sees the difference and cannot tell which of the two columns moved.", "Two, distinguished by the sign the engine attaches to the flag.", "Two, since a heavier annulus is a design choice and a lighter far side is a failure.", "One, but only while both densities stay below the value at which the differential head changes its sign."]'::jsonb, 0, 'The engine does not distinguish them, which is why a negative row cannot on its own tell you how the well arrived there.'),
  ('integrity', 'intermediate', 'module', 'm05-when-it-cannot-be-pressured', 9, 'Which two lines at the end of the row builder decide the clamp and the flag?', '["The reported MAASP is the larger of zero and the governing row, and the flag is set when that row is below zero.", "The mean of the rows is reported and the flag counts the negatives.", "Any negative row is reset to zero and the flag names the first of them.", "The reported MAASP is the smallest positive row, and the flag rises when a row has had to be excluded to find one."]'::jsonb, 0, 'So a governing row of -104271.45154356956 Pa is reported as a MAASP of 0 Pa with the flag set alongside it.'),
  ('integrity', 'intermediate', 'module', 'm05-when-it-cannot-be-pressured', 10, 'Which row is the negative flag asked about, and why that one?', '["The first row supplied, because the engine preserves input order.", "The governing row, since it is the minimum, so no other row can be negative while that one is not.", "Every row in turn, so the flag counts how many elements are past their rating.", "The deepest row, because the differential head grows with vertical depth and will always run out there first."]'::jsonb, 1, 'That choice follows from module 2, where the reduction over the rows keeps the smallest allowable rather than the first.'),
  ('integrity', 'intermediate', 'module', 'm05-when-it-cannot-be-pressured', 11, 'Why does the engine refuse to hand a negative figure out as the MAASP?', '["Because a negative pressure has no physical meaning.", "Because the permit system rejects any value outside its range.", "Because a reader or a piece of software is likely to take its magnitude, treat it as a rounding artefact, or drop the sign.", "A MAASP feeds charts, permits and alarm setpoints, and each of those recovers an allowance from a negative."]'::jsonb, 3, 'Reporting the raw negative would not read as a warning at all, it would be available for misreading in the unsafe direction.'),
  ('integrity', 'intermediate', 'module', 'm05-when-it-cannot-be-pressured', 12, 'The clamp changes the headline value. What happens to the individual rows?', '["They are clamped at zero as well, for consistency.", "They are dropped, because only the governing row is returned.", "Each row keeps its own allowable exactly as computed, sign and all, so the diagnostic figure survives the clamp.", "They are rescaled so that the smallest row reads zero, while all of the other rows keep their original spacing above it."]'::jsonb, 2, 'That split matters because a row missing by 104271.45154356956 Pa is a fluid change, while one missing by several MPa is not.'),
  ('integrity', 'intermediate', 'module', 'm05-when-it-cannot-be-pressured', 13, 'A reported MAASP of zero with the flag raised is not a tight operating limit. What is it?', '["A limit to respect, meaning no pressure may be added.", "A placeholder until the far side density has been confirmed.", "A statement that the load which used the envelope up is the fluid column, not anything you are choosing to apply.", "An instruction to bleed the annulus down to atmospheric pressure and hold it there until the element can be properly re-rated."]'::jsonb, 2, 'Treating it as a limit to respect and then carrying on is precisely the misreading the flag exists to prevent.'),
  ('integrity', 'intermediate', 'module', 'm05-when-it-cannot-be-pressured', 14, 'How does the module ask you to word the finding a negative row produces?', '["The well as configured cannot hold what is already in it, with the element and its raw allowable named.", "The annulus has failed its most recent pressure test.", "The governing element is leaking and must be isolated at once.", "The maximum allowable annulus surface pressure for this well has been revised downwards to zero for the present."]'::jsonb, 0, 'Three words carry that sentence: configured makes it a state, already puts it before any operation, and cannot hold points at the element.'),
  ('integrity', 'intermediate', 'module', 'm05-when-it-cannot-be-pressured', 15, 'Which of these does the tier''s negative finding deliberately not settle?', '["The identity of the element that governs.", "Whether the element has failed or is leaking, how the well got here, and which of the fixes to prefer.", "Whether the reported value has been clamped at zero.", "The raw allowable of the governing row, which the engine discards as soon as the headline figure has been clamped at zero."]'::jsonb, 1, 'What the finding does oblige is that somebody goes back to the inputs and establishes which of them is wrong or has to change.'),
  ('integrity', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'At the close of a design review a graduate asks Adaeze what all the tier''s quantities have in common. Which reply is hers?', '["Each one is a pressure read at the wellhead.", "Each one is scaled by the same RP 90 role factor before being reported.", "Each one is a difference rather than a level, and the well''s limit is the smallest gap that it has.", "Each one is an absolute pressure referenced to the datum the survey uses, which is why vertical depth enters every term."]'::jsonb, 2, 'A rating is a difference the wall can stand, a head is a difference between two columns, and an allowable is a rating less a head.'),
  ('integrity', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'Tunde writes down the strings he believes are weak and leaves the shoe formation off his candidate list. What has he risked?', '["An element that never became a row cannot govern, so the row nobody wrote is the failure mode of this method.", "Nothing, since the engine adds a shoe row by default.", "A throw from the engine, because a list without a shoe is rejected.", "A reported limit that is too low, because the shoe carries a factor of 1.0 and would have raised the governing allowable."]'::jsonb, 0, 'Step one asks for the string outside the annulus, the string inside it, the hanger, the wellhead and the shoe formation at the bottom.'),
  ('integrity', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'A data sheet quotes 2400 m beside the governing element, while the survey Priya pulls gives 2048.29303343 m. Which belongs in the row?', '["The tally value, which is what the completion records hold.", "Either value, as long as one convention is applied across the whole table.", "The measured value, since the engine converts depths to vertical internally from the minimum curvature survey it holds.", "The vertical one, because head is a vertical column and the other charges hole that contributes nothing."]'::jsonb, 3, 'The conversion belongs to the survey engine and this one does not attempt it, so a depth has to arrive already vertical.'),
  ('integrity', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'Ingrid opens a colleague''s table and finds it built on raw ratings with no factors applied anywhere. Which step was skipped?', '["Step five, the reduction taken over the rows.", "Step three, which asks what job each element is doing and applies the factor that the role carries.", "Step two, which takes each depth from the survey rather than from the tally.", "No step was skipped, since a table built on raw ratings is the MAASP path and factors belong only to the MAWOP one."]'::jsonb, 1, 'The engine refuses a role it does not recognise rather than guessing, and it refuses a factor of zero or below or greater than one.'),
  ('integrity', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'Marcus argues that one backup density should be applied across every row for consistency. Why does Sian disagree?', '["Each element has its own far side, so two rows in one table can legitimately carry different backup densities.", "Because the engine averages the supplied backups in any case.", "Because consistency is a reporting convention rather than an engineering one.", "Because the backup density is fixed by the fluid the well was completed with, and only one such fluid exists per well."]'::jsonb, 0, 'The head subtracted from a row is the annulus density less that element''s own far side, times 9.80665, times its vertical depth.'),
  ('integrity', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'Rosa works down a MAWOP table and stops at the first row that looks limiting. What has she misread about step five?', '["Nothing, provided the rows were supplied in depth order.", "The governing value is the minimum over every row, not the earliest entry that looks convincing.", "She wanted the largest row instead, since it bounds all of the others.", "She wanted the shallowest row instead, because a shallow element carries the least help from any fluid column."]'::jsonb, 1, 'The reduction keeps the smallest allowable as it scans, and the incumbent it starts from is there only to be beaten.'),
  ('integrity', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'Hakim expected the outer casing to govern and the table hands the limit to a different string. Which check settles it?', '["Re-running the case with all of the roles removed.", "Confirming the outer casing is the deepest of the candidates.", "Ranking the governing value against every row he wrote, because the module 3 inversion behaves in exactly this way.", "Checking the reported figure is above zero, since a governing element can only change identity once the clamp has fired."]'::jsonb, 2, 'On the published well a 40000000 Pa outer casing allows 17606905.05541501 Pa while the weaker 35000000 Pa liner allows 26855228.63225454 Pa.'),
  ('integrity', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'Nadia''s capstone case comes back at zero with the flag up. What belongs in the line she submits?', '["A limit of zero, written onto the operating card.", "A request to re-run the case after the annulus has been bled to atmospheric.", "A statement that the governing element has failed, since a clamped result and a failed element describe one condition.", "A finding that the well cannot hold what is already in it, naming the element and its raw allowable."]'::jsonb, 3, 'The raw figure earns its place because a row missing by a small margin is a fluid change, while one missing by several MPa is not.'),
  ('integrity', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'Yusuf edits a single far side density in his capstone table and watches several rows shift. What should he conclude?', '["The engine has re-sorted the table around the new entry.", "More than one input moved, because a far side density can only affect the row that owns it.", "The annulus fluid density is derived from the far side entries.", "The rows are coupled through the reduction, so any edit propagates into every row sitting above the minimum."]'::jsonb, 1, 'That independence is what makes a table readable, since any movement in the headline figure can be attributed to one line.'),
  ('integrity', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'Bea asks whether anything in this tier can make an annulus pressure stop mattering. What is the honest reply?', '["It can, once the governing element has been re-rated.", "It can, by clamping the reported limit at zero and raising the flag.", "It can, since a MAWOP built on the RP 90 factors is already the pressure at which an annulus stops being a concern.", "It cannot, because every remedy available is a change to the well itself rather than a change to the sum."]'::jsonb, 3, 'Every tool here manages a well still in service, with a valve, a gauge and somebody watching the reading.'),
  ('integrity', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'A supervisor hands Femi a gauge reading and asks this engine whether it is thermal or a leak. What can Femi report?', '["Only how much surface pressure the bounding elements will carry, since cause, rate and time sit outside.", "The cause, once the annulus has been bled down twice.", "The time to rebuild, which the flag reports alongside the clamp.", "Both the cause and the limit, because the engine weighs the observed pressure against the thermal build its rows predict."]'::jsonb, 0, 'This tier builds rows, picks a governing row, clamps the result and raises a flag, and it computes no leak rate whatsoever.'),
  ('integrity', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'Asked at handover which habit to carry forward into abandonment work, Jonas names one. Which is it?', '["Always quote pressures in Pa rather than in bar.", "Always treat the deepest element in the list as the one that governs.", "Keep asking what the difference is between, since a plug holds when its resistance exceeds what pushes on it.", "Always apply the outer casing factor of 0.5, because nothing can be inspected once a well is left unattended."]'::jsonb, 2, 'The habit survives the change of subject because a plug that holds is itself a difference, resistance set against load.'),
  ('integrity', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'Owen asks what really changes once a well is permanently abandoned. Which change does the closing lesson name?', '["The annulus fluid is displaced to a heavier brine.", "The RP 90 role factors are all replaced by a single conservative factor of one.", "The governing element becomes the wellhead, since it is the only part of the well still accessible after abandonment.", "The operator leaves the loop, so whatever stands between source and surface has to work unattended."]'::jsonb, 3, 'The object of study changes with it, from an element with a rating to a plug, a column of set cement placed across the hole.'),
  ('integrity', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'A reviewer asks Callum what he may now claim about annulus pressure limits. Which claim does the tier support?', '["That he can predict when an annulus will build pressure.", "That he can rank the available fixes once a row has gone negative.", "That he can defend a limit on a live annulus and name the element, the depth and the role factor behind it.", "That he can say whether a gauge reading is acceptable, because a limit and an acceptance criterion are one test."]'::jsonb, 2, 'It also covers saying whether the answer was a pressure at all, since a clamped zero with the flag raised is a finding instead.'),
  ('integrity', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'Aisha asks which neighbouring courses supply the parts this tier only assumes. Which pairing is correct?', '["Well Control supplies both the trajectory and the slurry.", "Cementing designs the slurry and its placement, and Well Design and Surveys supplies the trajectory.", "Cementing supplies the trajectory, while Well Control designs the slurry and places it.", "Well Design and Surveys designs the slurry, while Cementing handles the pressure source for as long as a well stays open."]'::jsonb, 1, 'Well Control is the third neighbour, taking the pressure source while the well is still open rather than after it is closed.'),
  ('integrity', 'intermediate', 'final', null, 1, 'A supervisor bleeds the A annulus to zero on Monday and finds the same reading on Friday with the well unchanged. What may this tier contribute?', '["The rebuild points to a communication path, but the engine judges any build against the same limit.", "The engine reports the cause once the bleed record is supplied.", "The engine separates thermal expansion from communication by comparing the rate of rebuild against the production rate it holds internally.", "Nothing at all, because a pressure that returns after a bleed is outside every quantity this tier computes."]'::jsonb, 0, 'Sustained casing pressure is a barrier finding, and the annulus limit tells you only whether the reading being carried overloads a bounding element.'),
  ('integrity', 'intermediate', 'final', null, 2, 'Choosing between a 1030 kg/m3 and a 2000 kg/m3 packer fluid, which consequence for the published limiting element should weigh on the decision?', '["Neither choice matters until the well is brought on and warms up.", "The heavier fluid raises the allowable, because a denser column resists any pressure arriving at the wellhead from the completion side.", "The heavier fluid cuts the allowable from 24000000 Pa to 4515713.910002284 Pa before any heating occurs.", "The two fluids differ by less than the tolerance the engine carries on a hydrostatic term."]'::jsonb, 2, 'The column stands on every element below it, so the packer fluid is part of the limit rather than a neutral completion detail.'),
  ('integrity', 'intermediate', 'final', null, 3, 'A wellhead rated below every string is added to the candidate list at zero vertical depth. How does its row behave when the fluids change?', '["It moves with every other row, because all rows share one fluid.", "It holds still, since with no vertical depth its head is zero and only the factored rating remains.", "It falls faster than any other row, because a surface element has no far side column to offset it.", "It is refused, because the engine throws on any element whose depth is not above zero."]'::jsonb, 1, 'A tree or wellhead sits at the top of the annulus and feels surface pressure with no help from any fluid column.'),
  ('integrity', 'intermediate', 'final', null, 4, 'Asked whether a measured annulus pressure ought to be there at all, what can an engineer answer from this tier alone?', '["That the pressure is acceptable for as long as the gauge reading sits below the limit the table reports for that annulus.", "That the pressure belongs whenever the governing row is a casing burst rather than a tubing collapse, since burst rows tolerate a live source.", "That the pressure is a thermal build unless the negative flag has been raised on the table.", "Nothing, because that is the barrier envelope question and this tier only prices what the elements will carry."]'::jsonb, 3, 'Whether a pressure should exist is the Associate tier''s question about envelopes, answered by elements and their statuses rather than by allowables.'),
  ('integrity', 'intermediate', 'final', null, 5, 'Deleting the 4-1/2 tubing collapse candidate on the grounds that tubing is not casing raises the reported limit. What has that achieved?', '["A correct limit, as collapse belongs in a separate calculation.", "A safer limit, because dropping the weakest candidate returns the reviewer to a casing string a production supervisor can actually act on.", "Nothing for the well, because an element left off the list cannot govern and the 9-5/8 row is quoted instead.", "A throw, since the engine checks the candidate list it is given against the completion schematic recorded for the well."]'::jsonb, 2, 'The row you never wrote is the one failure mode this method has, which is why step one asks for every bounding element rather than the ones thought weak.'),
  ('integrity', 'intermediate', 'final', null, 6, 'An engineer objects that a shoe formation cannot be limiting because its factor of 1.0 holds nothing back. Where does the objection fail?', '["The factor only scales a limit, so a low fracture strength at depth can still produce the smallest allowable.", "A shoe carries no depth, so its row is never compared.", "The objection is sound, because the engine excludes shoe formations from the reduction and treats them as advisory rows only.", "Shoe formations are handed a factor of 0.5 in the same way an outer casing is."]'::jsonb, 0, 'Pressure in an annulus open to a formation can break it down and broach, whatever the casing around it is rated to.'),
  ('integrity', 'intermediate', 'final', null, 7, 'One pressure is applied in an annulus and a reviewer lists only the strings that could burst. Which loading is missing from the list?', '["The shoe formation, which is loaded in tension by the column.", "None, because an annulus can only load the walls that bound it in burst.", "The wellhead, which is loaded in shear where the annulus outlet leaves the spool.", "The string inside the annulus, squeezed in collapse by the very same pressure that bursts the one outside."]'::jsonb, 3, 'The pipe that yields first is whichever has least room left, so the comparison has to run across both senses at once.'),
  ('integrity', 'intermediate', 'final', null, 8, 'Two rows in a table come back within a few tens of thousands of Pa of each other. What does that narrow margin oblige?', '["The engine reports the mean of the two allowables, since neither row can be preferred while they sit that close together.", "Both input sets have to be right, since a modest fluid change can hand the limit to a different failure mode.", "Nothing, because the reported limit is the same either way and the identity of the governing element is a presentational detail.", "The earlier of the two rows should be deleted so the reduction has a clear winner."]'::jsonb, 1, 'The published margin of 5701240.88444588 Pa is wide, so small revisions there move the number without changing who governs.'),
  ('integrity', 'intermediate', 'final', null, 9, 'A test case supplies its weakest element first, and it passes. Why does passing prove less than it appears to?', '["With the minimum already at the top, a reduction that simply returned the first row would answer correctly.", "It proves nothing, since a single case cannot verify arithmetic.", "It proves the pick, because the engine sorts the rows internally before the reduction runs and the ordering is therefore irrelevant.", "It proves only the rating term, since the hydrostatic term on each row is verified against a separate oracle of its own."]'::jsonb, 0, 'Ordering is the variable a case has to move, which is why a sibling engine shipped a fold that took the bottom of a section rather than searching it.'),
  ('integrity', 'intermediate', 'final', null, 10, 'An element is believed to have no capacity left, so a factor of zero is entered against it. Where does that element belong?', '["In the table with a factor of 0.5 applied for an outer role.", "In the table exactly as entered, because the engine accepts a factor of zero and reports the row as allowing nothing at surface.", "In the Associate tier''s barrier envelope as a failed element, since a derate cannot express a failure.", "In a separate MAWOP run, where a factor of zero is permitted but a factor above one is not."]'::jsonb, 2, 'The engine refuses any factor outside the interval above zero and up to one, and it names the element when it throws.'),
  ('integrity', 'intermediate', 'final', null, 11, 'A displacement drops the annulus fluid and the fluid behind one wall by the same 170 kg/m3. What does that element''s row do?', '["It rises, since a lighter annulus always buys allowable.", "It stays exactly where it was, because only the difference of the two densities enters the head.", "It falls, because the far side lost more absolute contribution than the annulus did.", "It is rebuilt from the new densities and the governing name changes with it."]'::jsonb, 1, 'An annulus at 1200 kg/m3 with 1030 behind it loads a wall exactly as an annulus at 1030 with 860 behind it does.'),
  ('integrity', 'intermediate', 'final', null, 12, 'The fixture carries 3414771.788968672 Pa of head at a sensitivity of 20086.892876286307 Pa per kg/m3. What density difference is that?', '["A difference of 1200 kg/m3, since the head is charged on the annulus column taken whole rather than on a gap.", "A difference of 2048 kg/m3, since the head is charged over the element''s true vertical depth rather than over its density gap.", "A difference of 500 kg/m3, matching the backup on the governing candidate.", "A difference of 170 kg/m3, which is 1200 kg/m3 in the annulus against 1030 kg/m3 on the far side."]'::jsonb, 3, 'The sensitivity is g multiplied by the true vertical depth, so dividing any head by it recovers the density difference that produced it.'),
  ('integrity', 'intermediate', 'final', null, 13, 'Could a table ever report a positive governing value while one of its other rows is negative?', '["Yes, and the flag would then be raised on that row.", "Yes, whenever the negative row belongs to a shoe formation, since formation rows are excluded from the reduction that picks the limit.", "No, because the governing row is the minimum, so nothing below zero can sit above it in the table.", "Yes, because the clamp is applied to each row as it is built, well before the pick over the rows is made."]'::jsonb, 2, 'The clamp comes after the pick and the flag reports on that same governing row, which is why they have to be read as a pair.'),
  ('integrity', 'intermediate', 'final', null, 14, 'A supervisor receives the figure 11905664.170969129 Pa and nothing else. What has to travel with it?', '["The governing element''s name and the margin to the next row, since the name says what would fail and where.", "The date of the last annulus bleed carried out on that well.", "The rejected candidates and the reason each was thrown out, so the supervisor can confirm the list was complete before the run.", "The measured depth of each element, so the head terms can be recomputed by hand."]'::jsonb, 0, 'On this well the limit is set by an inner string being squeezed, so the mitigation is pressure inside the tubing rather than anything about the casing.'),
  ('integrity', 'intermediate', 'final', null, 15, 'A tieback puts a second annulus outside a string that had been logged as inner casing. What happens on paper?', '["Nothing, as the steel and its rating are unchanged.", "Its hydrostatic term doubles, since head is charged from both columns at once.", "Its role stays as it was until a caliper log confirms wear at the new outer position.", "Its role becomes outer casing burst, the factor drops from 0.8 to 0.5 and the rated term loses 12000000 Pa."]'::jsonb, 3, 'A role is assigned deliberately and in writing per candidate, because the operating card records a property of the job rather than of the pipe.'),
  ('integrity', 'intermediate', 'final', null, 16, 'Two proposals sit on one 40000000 Pa string: reclassify it from an outer to an inner burst role, or weight the column outside it from 1030 to 1200 kg/m3. Which buys more?', '["The weight up, because a fluid change needs no regulator.", "The reclassification, worth 12000000 Pa of rated term against 2393094.944584991 Pa from the fluid.", "They are worth the same, since the RP 90 factors were calibrated so that a role step matches the head a typical column change produces.", "Neither, as the two levers act on the same term and therefore cannot be added."]'::jsonb, 1, 'The role change moves the rated term alone while the fluid moves the head alone, so the two are independent and both reach the surface figure in full.'),
  ('integrity', 'intermediate', 'final', null, 17, 'A caliper log finds metal loss below the wellhead on an inner casing and 0.6 is written against a role default of 0.8. Is that legitimate?', '["Yes, a measurement beats a convention, and the role still travels with the row as the element''s kind.", "No, the role table is the only permitted source of a factor.", "No, because an explicit factor is consulted only when the role is missing, so the 0.8 default would still be applied to this row.", "Yes, but only if the same factor is then applied to every other candidate in the table, for consistency."]'::jsonb, 0, 'The lookup reads the candidate''s own factor first and falls back to the role table, so an override downwards on evidence is exactly the intended use.'),
  ('integrity', 'intermediate', 'final', null, 18, 'An outer casing is entered with an explicit factor of 0.9 and the row computes without complaint. What has just happened?', '["The engine has silently restored the 0.5 role default.", "The run has been made more conservative, since any factor written by hand replaces a convention that was never intended to bind a specific string.", "Half of the rating became nine tenths of it under cover of a data entry, and only review will catch it.", "The candidate has been thrown out, because 0.9 exceeds the outer casing default."]'::jsonb, 2, 'The engine refuses only a factor above one or at zero and below, so an upward override needs evidence that the role itself is wrong, recorded as a role change.'),
  ('integrity', 'intermediate', 'final', null, 19, 'A run stops because a candidate was spelled with an underscore in its role. Why is a stop better than a default?', '["A stop lets the engine renumber the rows in supplied order.", "A default of 1 would take the least trusted string at face value, so the throw names the candidate instead.", "A default would be acceptable whenever the candidate carries its own factor.", "The throw protects the reduction, which cannot compare rows built under different roles."]'::jsonb, 1, 'An unrecognised role is either a typing error or a convention the engine has not been taught, and both deserve a stop rather than a guess.'),
  ('integrity', 'intermediate', 'final', null, 20, 'A reviewer ranks the three published candidates by rating alone and predicts which governs. Where does that prediction go wrong?', '["Ranking by rating is sound here, because every candidate on this well happens to carry the same role factor.", "It goes wrong only on the tubing, because collapse ratings are quoted on a different basis from burst ratings and cannot be ranked beside them.", "The ranking fails only when two candidates sit at the same vertical depth.", "The 40000000 Pa casing allows less than the 35000000 Pa liner, so roles and fluids reorder the rows."]'::jsonb, 3, 'The published inversion has the 40000000 Pa outer casing at 17606905.05541501 Pa against 26855228.63225454 Pa for the weaker liner.'),
  ('integrity', 'intermediate', 'final', null, 21, 'A repeat leak off test at a shoe returns a lower fracture strength than the previous one. Which part of that candidate''s row moves?', '["Only the head, which is charged against the shoe depth.", "Both terms, because a fracture strength enters the row as a limit and also as the far side pressure the formation holds up.", "Only the rated term, and at a factor of 1.0 it moves one Pa of allowable for each Pa of limit lost.", "Neither, since a shoe formation is carried as a note beside the table rather than as a row inside it."]'::jsonb, 2, 'A role change and a limit change both act on the rated term alone, so the hydrostatic term cannot know which of them happened.'),
  ('integrity', 'intermediate', 'final', null, 22, 'A deviated well''s table is built from tally depths because the survey was not opened. In which direction does every row move?', '["Every head is overstated and every allowable understated, so the error hides itself as conservatism.", "Only the deepest row moves, and it moves upwards.", "Heads are understated on the shallow rows and overstated on the deep ones, so the governing name changes while the reported limit holds.", "Nothing moves until the deviation exceeds the tolerance the engine applies to a depth."]'::jsonb, 0, 'The published element sits at 2400 m measured against 2048.29303343 m vertical, and the conversion belongs to the survey engine rather than to this one.'),
  ('integrity', 'intermediate', 'final', null, 23, 'One candidate in an otherwise healthy table is clamped to zero, and its far side column turns out to be empty. What belongs in the finding?', '["That the element has failed and the annulus has no barrier.", "That the far side was defaulted to the annulus density, cancelling the head.", "That the clamp fired on a row other than the governing one, so the flag can be ignored.", "That a blank was read as zero density, the harshest far side available, and the input has to be established."]'::jsonb, 3, 'The default is silent because a silent severe assumption is safer than a silent generous one, and zero should be a decision that can be defended.'),
  ('integrity', 'intermediate', 'final', null, 24, 'An element allows 40069514.30102905 Pa against an unfactored limit of 30000000 Pa. What must be defended before that goes on an operating card?', '["That the rating was quoted at the correct temperature.", "That the 2000 kg/m3 column outside the wall stays there, since the whole excess above the rating rests on it.", "That the engine applied the factor, because an allowable above the raw limit can only arise when a derate has been left out of the rated term.", "That the element sits deep enough for the head to be charged over the full column."]'::jsonb, 1, 'A wall with a much heavier column outside it really can take more pressure inside before the difference across it reaches the rating.'),
  ('integrity', 'intermediate', 'final', null, 25, 'Weighting up the B annulus is proposed to protect the string inside it. Which other rows move, and how?', '["Every row on the string outside that annulus loses allowable, at the same rate per kg/m3 as the gain.", "None, because a row only ever sees its own far side.", "Rows on both neighbouring strings gain, since a denser column presses outwards and inwards with equal force across each wall it touches.", "Only rows at the same vertical depth move, and they move in the same direction as the row being helped."]'::jsonb, 0, 'The same fluid enters one row as a backup that adds and the next as an annulus fluid that subtracts, so a fluid choice moves margin rather than making it.'),
  ('integrity', 'intermediate', 'final', null, 26, 'Under what condition would a weight up cost one element exactly what it buys another?', '["When both carry the same role factor and the same rating.", "When the two elements bound the same annulus, since the column between them is charged once and shared equally across the pair of walls.", "When both sit at the same true vertical depth, because the slope is g multiplied by that depth alone.", "Whenever the annulus is weighted by less than the sensitivity of the shallower row."]'::jsonb, 2, 'The published candidates sit at 1435.457478934607 m, 1167.3419238429642 m and 997.0400302755012 m, so the two effects rarely cancel on a real well.'),
  ('integrity', 'intermediate', 'final', null, 27, 'The published governing row is a factor of 0.75 on a 25000000 Pa collapse rating with 500 kg/m3 behind it. Which half of the row would you attack first?', '["The rating, which can be restored by a re-rate on paper.", "The fluids, since a light far side charges the heaviest head of the three despite the shallowest depth.", "Neither half, because the two terms are multiplied together and any change to one of them is absorbed by the other before it reaches surface.", "The factor, as a quarter of the rating is the largest single deduction in the row."]'::jsonb, 1, 'The 7 in liner is the least constraining candidate largely because it carries 1100 kg/m3 behind it, denser than the annulus fluid itself.'),
  ('integrity', 'intermediate', 'final', null, 28, 'A gas lifted well has unloaded its tubing, so the completion string has close to a gas column inside it. Is a backup of zero a lapse here?', '["Yes, because no real completion fluid reaches zero density, so the entry describes a condition the well cannot be in.", "Yes, since a gas column still carries a density of several tens of kg/m3 and the engine refuses any backup entered below that figure.", "No, and the engine records that the value was chosen rather than defaulted.", "No, it is a defensible modelling choice, and what matters is that the entry was decided rather than skipped."]'::jsonb, 3, 'The far side crossing on the fixture sits at 5.191019446649534 kg/m3, so a very light gas and a true void are not far apart in their effect.'),
  ('integrity', 'intermediate', 'final', null, 29, 'Two wells both report zero with the flag raised. What separates a fluid change from something much worse?', '["The order in which the candidates were supplied to the engine.", "Nothing available here, because the clamp overwrites the row values as well as the headline and both wells now read identically.", "The governing row''s raw allowable, which the clamp leaves untouched so the size of the miss stays readable.", "The negative flag, which is raised once for a small miss and a second time when the row is several MPa past."]'::jsonb, 2, 'A row that missed by 104271.45154356956 Pa is a fluid change, while a row several MPa past its rating is not.'),
  ('integrity', 'intermediate', 'final', null, 30, 'A downstream reporting tool takes the magnitude of any pressure handed to it. What would a raw negative become in it?', '["A positive allowance on a well that has none, which is precisely the misreading the clamp prevents.", "An alarm, since the tool rejects any value below zero.", "A conservative limit, because the magnitude of a negative row is always smaller than the allowable the same element would carry when positive.", "A rounding artefact near zero, which is the same outcome the clamp itself produces."]'::jsonb, 0, 'A MAASP goes onto a chart, into a permit and into an alarm setpoint, and everything downstream treats it as the answer to how much may be applied.'),
  ('integrity', 'intermediate', 'final', null, 31, 'An annulus has been weighted from 1030 to 2250 kg/m3 with the far side unchanged. What comes back, and can the cause be named?', '["A throw, because 2250 kg/m3 is outside the accepted range.", "A row of exactly zero with the flag down, since the engine substitutes the break even density.", "A positive row, as the crossing on this element sits above 2250 kg/m3.", "A row at -506009.3090692945 Pa clamped to zero with the flag up, and no, the row sees only the difference."]'::jsonb, 3, 'A heavier annulus and a lighter far side are one subtraction reached from two directions, so the arithmetic cannot say which of them moved.'),
  ('integrity', 'intermediate', 'final', null, 32, 'How much density does the fixture need on its far side before it has any operating envelope at all?', '["About 1030 kg/m3, the brine the published case carries behind the wall, below which the row has nothing left.", "A little over 5 kg/m3, so the gap between working and past its rating is measured in single figures.", "About 170 kg/m3, which is the density difference that produces the head the element is already carrying at that depth.", "None at all, because a rated term of 24000000 Pa cannot be used up by a column."]'::jsonb, 1, 'The crossing sits at 5.191019446649534 kg/m3, which is why a blank field and a light gas column are not the same statement about a well.'),
  ('integrity', 'intermediate', 'final', null, 33, 'A duty manager proposes logging the clamped zero as an operating restriction and carrying on. Why is that the misreading the flag exists to prevent?', '["No envelope is left to plan inside, since the load that used it up is the standing column and not an operation.", "The restriction would expire when the well is next bled down.", "The zero is a rounding of a very small positive allowable, so a restriction set at that value is marginally unconservative rather than wrong.", "The flag is asked about the runner up row rather than the governing one, so the restriction is logged against the wrong element."]'::jsonb, 0, 'The finding is that the well as configured cannot hold what is already in it, and what it obliges is that somebody goes back to the inputs.'),
  ('integrity', 'intermediate', 'final', null, 34, 'Three responses follow a clamped result: lighten the annulus, restore the far side column, or re-rate the element on evidence. What does this tier add?', '["It selects the cheapest of the three and reports it with the flag.", "It rules out the re-rate, because a factor override is the one response the engine refuses to accept after a negative row has been recorded.", "It prices each input change through the sensitivity and ranks none of them, since all three sit outside it.", "It rules out lightening the annulus, as the annulus density is not an input to the head."]'::jsonb, 2, 'The tier does not say the element has failed, is leaking, or when it might, and every remedy is a change to the well rather than to the sum.'),
  ('integrity', 'intermediate', 'final', null, 35, 'A clamped row belongs to an outer casing that can be neither inspected nor repaired without a sidetrack. Which lever is left?', '["The role factor, which may be raised once a test has passed.", "The differential, because a far side column acts on a string you cannot inspect, repair or re-rate.", "None within this tier, since an outer casing carries the harshest factor already and the engine will not accept a further derate on it.", "The measured depth, which can be swapped for the vertical depth to recover a little of the lost head."]'::jsonb, 1, 'The gain lasts only as long as the column does, so an annulus that can be bled or can gas up above a leak is a weak place to rest a margin.'),
  ('integrity', 'intermediate', 'final', null, 36, 'Leila finds that the row she expected to govern is not the smallest in her capstone table. What should she do?', '["Resupply the candidates with the expected row first, so that the reduction is given the incumbent it was designed around.", "Rebuild the table, since a governing row that contradicts the design intent shows a far side density entered against the wrong candidate.", "Report both rows, and let the reviewer decide which of the two limits applies.", "Accept the table, because an expectation ranked by pipe rather than by role is what the inversion catches."]'::jsonb, 3, 'The second check before submitting is that the governing value is the smallest row and has not been assumed to be the first.'),
  ('integrity', 'intermediate', 'final', null, 37, 'Dmitri opens a capstone well whose annulus fluid density was never recorded. How far can he get?', '["As far as the rated terms, which need no fluid at all.", "All the way, because an omitted annulus density defaults to zero in the same way a missing far side density does.", "Nowhere, since the engine refuses any density that is not positive before it builds a single row.", "As far as the governing name, which depends on the order supplied rather than on the annulus fluid."]'::jsonb, 2, 'The annulus fluid is the one property the annulus itself owns, and it is the only input shared by every row in the table.'),
  ('integrity', 'intermediate', 'final', null, 38, 'Anneke is asked why a casing designer and a production supervisor are quoted different figures on one annulus. What is her answer?', '["The designer gets the bare physical allowable and the supervisor the working limit under the role factors.", "The two figures come from different annuli on the same well.", "The supervisor receives the larger figure, because an operating limit is set before any derate and the design case then applies the factors.", "Only the supervisor''s figure is clamped at zero, so the two differ whenever a row is negative."]'::jsonb, 0, 'MAASP is the physical question of what the elements will take, and MAWOP is the operating question of what will be allowed.'),
  ('integrity', 'intermediate', 'final', null, 39, 'Kofi calls the MAWOP case of 11905664.170969129 Pa a correction of the MAASP fixture at 20585228.21103133 Pa. What is wrong with that?', '["The second figure is larger once the clamp has been applied.", "Nothing, provided both were run on the same annulus fluid at the same depth.", "The fixture was run at a measured depth while the MAWOP case used vertical depths.", "Two things moved at once, a different element list and factors by role, so neither figure corrects the other."]'::jsonb, 3, 'Comparing the two tells you nothing until one of the element list or the factor authority is held fixed.'),
  ('integrity', 'intermediate', 'final', null, 40, 'After the whole tier, Mei asks what an annulus limit still cannot tell her. Which answer is right?', '["Which element governs, once several rows sit close enough together that a small revision could reorder them.", "Whether the pressure is thermal or a leak, how fast it builds, and whether it should be there at all.", "How much of the rating a role holds back, since the RP 90 table is an argument that can be replaced by a local convention.", "What the head is worth per kg/m3, which needs a survey the engine does not read."]'::jsonb, 1, 'Cause, rate and time sit outside the engine, and the question of whether a pressure belongs is answered by the barrier envelope instead.'),
  ('integrity', 'intermediate', 'final', null, 41, 'Rafael''s governing row wins by 5701240.88444588 Pa and a colleague then revises one rating slightly. What follows?', '["The reported limit shifts and the identity of the governing element does not, because the margin is wide.", "The revision is refused until the whole table is rebuilt.", "The governing name changes, since any revision to a rating enters the rated term in full and the rows sit within one order of magnitude.", "Neither the limit nor the name moves, as a rating reaches the row only through the role factor applied to it."]'::jsonb, 0, 'A narrow margin would mean two strings are effectively co-governing, and both sets of input data would then have to be right.'),
  ('integrity', 'intermediate', 'final', null, 42, 'Yara is told that rows verified to the last decimal make a wrong answer impossible. Which case from a sibling course answers that?', '["A survey engine that returned measured depth in place of vertical.", "A cement job that placed a balanced plug at the wrong depth, because the displacement volume came from a nominal rather than a caliper diameter.", "A casing check that reduced a load profile to the bottom of a section rather than searching it for the worst point.", "An economics run that summed a whole cash flow before the discount rate had been applied to any one of its periods."]'::jsonb, 2, 'Every pressure in that profile was correct, so the defect showed no error and no implausible number, only an optimistic answer on some of the cases.');
